WITH t_filtered AS (
    SELECT r.driverId, r.statusId
    FROM t_results r
    WHERE r.statusId = 3
)
SELECT * FROM t_filtered;

WITH t_final AS (
    SELECT t.driverId, d.forename, d.surname
    FROM t_filtered t
    INNER JOIN drivers d ON t.driverId = d.driverId
)
SELECT * FROM t_final;

WITH final_answer AS (
    SELECT COUNT(*) AS answer
    FROM t_final
)
SELECT * FROM final_answer;

